ee:message.ee:set-payload:
%dw 2.0
output application/json
---
{
  "error": {
    "code": "VALIDATION_ERROR",
    "message": "Request validation failed",
    "description": error.description default "The request contains invalid data",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "details": [
      {
        "field": error.detailedDescription default "unknown",
        "value": payload default null,
        "reason": error.description default "Invalid value provided"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "BAD_REQUEST",
    "message": "Invalid request format",
    "description": error.description default "The request format is invalid or malformed",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "details": [
      {
        "reason": "Request format validation failed",
        "message": error.detailedDescription default error.description
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "UNAUTHORIZED",
    "message": "Authentication required",
    "description": "Valid authentication credentials are required to access this resource",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "details": [
      {
        "reason": "Missing or invalid authentication token",
        "message": "Please provide valid authentication credentials"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "FORBIDDEN",
    "message": "Access denied",
    "description": "You do not have permission to access this resource",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "details": [
      {
        "reason": "Insufficient privileges",
        "message": "The provided credentials do not have access to this resource"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "NOT_FOUND",
    "message": "Resource not found",
    "description": "The requested resource could not be found",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "details": [
      {
        "resource": attributes.requestPath default "unknown",
        "reason": "Resource does not exist or has been removed"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "METHOD_NOT_ALLOWED",
    "message": "HTTP method not allowed",
    "description": "The HTTP method is not allowed for this resource",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "details": [
      {
        "method": attributes.method default "unknown",
        "resource": attributes.requestPath default "unknown",
        "allowedMethods": error.detailedDescription default "Check API documentation"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "BUSINESS_LOGIC_ERROR",
    "message": "Business rule violation",
    "description": error.description default "The request violates business logic constraints",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "details": [
      {
        "businessRule": error.errorType.identifier default "unknown",
        "reason": error.detailedDescription default error.description,
        "action": "Review business requirements and adjust request"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "RATE_LIMIT_EXCEEDED",
    "message": "Too many requests",
    "description": "Rate limit exceeded. Please retry after some time",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "details": [
      {
        "retryAfter": "60 seconds",
        "reason": "API rate limit exceeded"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SYSTEM_ERROR",
    "message": "Internal server error",
    "description": "A system error occurred while processing the request",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "details": [
      {
        "errorType": error.errorType.identifier default "SYSTEM_ERROR",
        "reason": "Internal system failure - please contact support if the problem persists"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "BAD_GATEWAY",
    "message": "Downstream service error",
    "description": "Error communicating with downstream service",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "details": [
      {
        "service": vars.currentService default "downstream",
        "reason": error.description default "Downstream service returned an error"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SERVICE_UNAVAILABLE",
    "message": "Service temporarily unavailable",
    "description": "The service is temporarily unavailable. Please try again later",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "details": [
      {
        "retryAfter": "300 seconds",
        "reason": "Service is temporarily unavailable"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "UNKNOWN_ERROR",
    "message": "An unexpected error occurred",
    "description": "An unexpected error occurred while processing the request",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "details": [
      {
        "errorType": error.errorType.identifier default "UNKNOWN",
        "reason": "Unexpected system error - please contact support"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "PROCESS_VALIDATION_ERROR",
    "message": "Process validation failed",
    "description": error.description default "The process request contains invalid data",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "layer": "PROCESS",
    "processStep": vars.currentProcessStep default "validation",
    "details": [
      {
        "field": error.detailedDescription default "unknown",
        "reason": error.description default "Invalid value provided"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "PROCESS_BUSINESS_ERROR",
    "message": "Business process validation failed",
    "description": error.description default "Business rule violation in process layer",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "layer": "PROCESS",
    "processStep": vars.currentProcessStep default "business-validation",
    "businessErrorCode": error.errorType.identifier default "UNKNOWN",
    "rollbackRequired": true,
    "details": [
      {
        "businessRule": error.errorType.identifier default "unknown",
        "reason": error.detailedDescription default error.description
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "PROCESS_SYSTEM_ERROR",
    "message": "System error in process layer",
    "description": "A system error occurred during process execution",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "layer": "PROCESS",
    "processStep": vars.currentProcessStep default "unknown",
    "rollbackRequired": vars.rollbackRequired default false,
    "details": [
      {
        "errorType": error.errorType.identifier default "SYSTEM_ERROR",
        "reason": "Process system failure - please contact support"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "PROCESS_UNKNOWN_ERROR",
    "message": "Unknown error in process layer",
    "description": "An unexpected error occurred during process execution",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "layer": "PROCESS",
    "processStep": vars.currentProcessStep default "unknown",
    "details": [
      {
        "errorType": error.errorType.identifier default "UNKNOWN",
        "reason": "Unexpected process error - please contact support"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SYSTEM_VALIDATION_ERROR",
    "message": "System API validation failed",
    "description": error.description default "The system API request contains invalid data",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "layer": "SYSTEM",
    "systemName": vars.systemName default "unknown",
    "retryable": false,
    "details": [
      {
        "field": error.detailedDescription default "unknown",
        "reason": error.description default "Invalid value provided"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SYSTEM_RESOURCE_NOT_FOUND",
    "message": "Resource not found in backend system",
    "description": "The requested resource was not found in the backend system",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "layer": "SYSTEM",
    "systemName": vars.systemName default "unknown",
    "resourceType": vars.resourceType default "unknown",
    "resourceId": vars.resourceId default "unknown",
    "retryable": false,
    "details": [
      {
        "resource": vars.resourceType ++ ":" ++ vars.resourceId,
        "reason": "Resource does not exist in backend system"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "BACKEND_SYSTEM_ERROR",
    "message": "Backend system error",
    "description": "Error communicating with backend system",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "layer": "SYSTEM",
    "systemName": vars.systemName default "unknown",
    "systemErrorCode": vars.systemErrorCode default "unknown",
    "systemErrorMessage": vars.systemErrorMessage default error.description,
    "retryable": vars.retryable default true,
    "details": [
      {
        "system": vars.systemName default "unknown",
        "reason": error.description default "Backend system failure"
      }
    ]
  }
}

%dw 2.0
output application/json
---
{
  "error": {
    "code": "SYSTEM_UNKNOWN_ERROR",
    "message": "Unknown error in system layer",
    "description": "An unexpected error occurred in the system API",
    "timestamp": now() as String { format: "yyyy-MM-dd'T'HH:mm:ss.SSSZ" },
    "correlationId": vars.correlationId default correlationId,
    "layer": "SYSTEM",
    "systemName": vars.systemName default "unknown",
    "retryable": false,
    "details": [
      {
        "errorType": error.errorType.identifier default "UNKNOWN",
        "reason": "Unexpected system API error - please contact support"
      }
    ]
  }
}
